head.script:
scwin.checkVal = function() {
	var dateString = (document.getElementById('wq_uuid_1_calendar_currentDate') || document.getElementById('mf_wq_uuid_1_calendar_currentDate')).innerText;
	var day = parseInt(dateString.substring(8, 10));
	var todayString = document.getElementsByClassName('w2calendar_selected')[0].innerText;
	return day == parseInt(todayString);
};
